function pathStroke(points,width,color){ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.lineWidth=width;ctx.lineCap='round';ctx.lineJoin='round';ctx.strokeStyle=color;ctx.stroke()}
function drawGround(camX,camY){ctx.fillStyle='#334a39';ctx.fillRect(0,0,world.w,world.h);for(let i=0;i<1150;i++){let x=rand(i,111)*world.w,y=rand(i,44)*world.h;let r=1+rand(i,43)*3;ctx.fillStyle=['#a1a46b11','#152b2018','#c5bd7c12','#243a2b17'][i%4];ctx.beginPath();ctx.ellipse(x,y,r*1.6,r,rand(i,9)*3.14,0,Math.PI*2);ctx.fill()}
// Soft paths winding between the clearing and the spring
pathStroke([[1040,850],[1110,833],[1184,850],[1250,825],[1300,790],[1353,774],[1410,758],[1460,743]],76,'#847b5e');pathStroke([[1040,850],[1110,833],[1184,850],[1250,825],[1300,790],[1353,774],[1410,758],[1460,743]],59,'#998969');pathStroke([[1040,850],[1110,833],[1184,850],[1250,825],[1300,790],[1353,774],[1410,758],[1460,743]],2,'#d4c19725');
// Lake and its banks
let g=ctx.createRadialGradient(1510,705,45,1535,725,330);g.addColorStop(0,'#426d6a');g.addColorStop(.72,'#355d5e');g.addColorStop(1,'#667055');ctx.fillStyle=g;ctx.beginPath();ctx.ellipse(1535,725,326,203,-.12,0,Math.PI*2);ctx.fill();ctx.fillStyle='#77907188';ctx.beginPath();ctx.ellipse(1535,725,307,185,-.12,0,Math.PI*2);ctx.fill();let waterGrad=ctx.createLinearGradient(1350,620,1700,850);waterGrad.addColorStop(0,'#4c7471');waterGrad.addColorStop(.5,'#346366');waterGrad.addColorStop(1,'#284d53');ctx.fillStyle=waterGrad;ctx.beginPath();ctx.ellipse(1535,725,283,162,-.12,0,Math.PI*2);ctx.fill();for(let i=0;i<70;i++){let x=1340+rand(i,90)*390,y=625+rand(i,91)*195;if(((x-1535)/283)**2+((y-725)/162)**2<.88){ctx.strokeStyle=`rgba(181,203,177,${.06+rand(i,33)*.15})`;ctx.lineWidth=.8+rand(i,94)*1.5;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+7+rand(i,33)*17,y-1+rand(i,47)*2);ctx.stroke()}}
// distant clearings and dappled meadow
for(let i=0;i<12;i++){let x=640+rand(i,72)*870,y=575+rand(i,73)*530;let grad=ctx.createRadialGradient(x,y,2,x,y,100);grad.addColorStop(0,'#b3a56a11');grad.addColorStop(1,'#b3a56a00');ctx.fillStyle=grad;ctx.beginPath();ctx.arc(x,y,100,0,6.28);ctx.fill()}
}
function drawTree(t){ctx.save();ctx.translate(t.x,t.y);let r=t.r;ctx.fillStyle='#15251d55';ctx.beginPath();ctx.ellipse(7,11,r*1.25,r*.65,0,0,6.28);ctx.fill();ctx.fillStyle='#604d36';ctx.fillRect(-4,0,8,19);if(t.type==='pine'){ctx.fillStyle='#2c4837';ctx.beginPath();ctx.moveTo(0,-r*1.55);ctx.lineTo(-r*.85,3);ctx.lineTo(r*.8,3);ctx.closePath();ctx.fill();ctx.fillStyle='#3c5a40';ctx.beginPath();ctx.moveTo(0,-r*1.15);ctx.lineTo(-r*.65,r*.22);ctx.lineTo(r*.65,r*.22);ctx.closePath();ctx.fill();ctx.fillStyle='#64704a66';ctx.beginPath();ctx.moveTo(0,-r*1.12);ctx.lineTo(-r*.12,-r*.54);ctx.lineTo(r*.48,r*.12);ctx.lineTo(r*.15,r*.15);ctx.closePath();ctx.fill()}else{let c=['#405d40','#486544','#3a573c','#526849'][Math.floor(t.h*4)];ctx.fillStyle=c;ctx.beginPath();ctx.arc(0,-r*.25,r,0,6.28);ctx.fill();ctx.fillStyle='#61734b88';ctx.beginPath();ctx.arc(-r*.27,-r*.56,r*.54,0,6.28);ctx.fill();ctx.fillStyle='#293f31aa';ctx.beginPath();ctx.arc(r*.3,-r*.1,r*.48,0,6.28);ctx.fill();ctx.fillStyle='#b0a86725';ctx.beginPath();ctx.ellipse(-r*.27,-r*.78,r*.4,r*.15,-.5,0,6.28);ctx.fill()}ctx.restore()}
function drawResource(r){ctx.save();ctx.translate(r.x,r.y);let color=r.type==='wood'?'#ad8b59':r.type==='stone'?'#9b9d8b':'#6d8954';ctx.fillStyle='#101b1670';ctx.beginPath();ctx.ellipse(0,8,19,7,0,0,6.28);ctx.fill();if(r.type==='wood'){ctx.rotate(-.25);ctx.fillStyle='#6d5139';ctx.fillRect(-19,-5,38,10);ctx.fillStyle='#ad8757';ctx.fillRect(-16,-5,29,4);ctx.fillStyle='#e2bc7d';ctx.beginPath();ctx.ellipse(-18,0,4,5,0,0,6.28);ctx.fill();ctx.fillStyle='#6e5137';ctx.beginPath();ctx.ellipse(-18,0,2,3,0,0,6.28);ctx.fill()}else if(r.type==='stone'){ctx.fillStyle='#747a70';ctx.beginPath();ctx.moveTo(-14,4);ctx.lineTo(-11,-7);ctx.lineTo(-3,-13);ctx.lineTo(9,-9);ctx.lineTo(15,1);ctx.lineTo(10,8);ctx.lineTo(-8,9);ctx.closePath();ctx.fill();ctx.fillStyle='#b0b4a1';ctx.beginPath();ctx.moveTo(-8,-7);ctx.lineTo(-2,-12);ctx.lineTo(7,-9);ctx.lineTo(1,-5);ctx.closePath();ctx.fill()}else{ctx.fillStyle='#526c46';for(let i=0;i<5;i++){ctx.beginPath();ctx.arc((i-2)*6,-4+Math.abs(i-2)*1.4,8,0,6.28);ctx.fill()}ctx.fillStyle='#9b4e43';for(const [x,y] of [[-6,-8],[4,-5],[1,1],[-9,-1],[9,-11]]){ctx.beginPath();ctx.arc(x,y,2.4,0,6.28);ctx.fill()}}ctx.restore()}
function drawFire(){if(!fire.lit)return;let flick=.9+Math.sin(elapsed*13)*.1;ctx.save();ctx.translate(fire.x,fire.y);let glow=ctx.createRadialGradient(0,-8,3,0,-8,230);glow.addColorStop(0,'#efaa4a55');glow.addColorStop(1,'#efaa4a00');ctx.fillStyle=glow;ctx.beginPath();ctx.arc(0,-8,230,0,6.28);ctx.fill();ctx.fillStyle='#44362a';ctx.beginPath();ctx.ellipse(0,2,18,8,0,0,6.28);ctx.fill();ctx.strokeStyle='#71573a';ctx.lineWidth=6;ctx.lineCap='round';ctx.beginPath();ctx.moveTo(-11,1);ctx.lineTo(10,-2);ctx.moveTo(-9,-3);ctx.lineTo(11,2);ctx.stroke();ctx.fillStyle='#f0a94f';ctx.beginPath();ctx.ellipse(0,-10,7*flick,14*flick,0,0,6.28);ctx.fill();ctx.fillStyle='#ffe2a1';ctx.beginPath();ctx.ellipse(0,-8,3.3,8*flick,0,0,6.28);ctx.fill();ctx.restore()}
function drawPlayer(){ctx.save();ctx.translate(player.x,player.y);ctx.scale(face,1);let bob=Math.sin(walk)*1.8;ctx.fillStyle='#10181377';ctx.beginPath();ctx.ellipse(0,8,12,6,0,0,6.28);ctx.fill();ctx.fillStyle='#29352f';ctx.fillRect(-6,-1+bob,5,10);ctx.fillRect(2,-1-bob,5,10);ctx.fillStyle='#6c805f';ctx.beginPath();ctx.ellipse(0,-4,9,10,0,0,6.28);ctx.fill();ctx.fillStyle='#516149';ctx.beginPath();ctx.moveTo(-8,-9);ctx.lineTo(0,-17);ctx.lineTo(9,-9);ctx.lineTo(6,1);ctx.lineTo(-6,1);ctx.closePath();ctx.fill();ctx.fillStyle='#c2a67b';ctx.beginPath();ctx.arc(0,-17,5.5,0,6.28);ctx.fill();ctx.fillStyle='#514533';ctx.beginPath();ctx.arc(0,-19,5.5,Math.PI,0);ctx.fill();ctx.fillStyle='#c9a565';ctx.fillRect(-8,-11,16,2);ctx.restore()}
function render(){ctx.clearRect(0,0,W,H);let camX=clamp(player.x, W*.45,world.w-W*.45),camY=clamp(player.y,H*.48,world.h-H*.48);if(world.w<W){camX=world.w/2}if(world.h<H){camY=world.h/2}ctx.save();ctx.translate(W/2-camX,H/2-camY);drawGround(camX,camY);
// tiny field flowers
for(let i=0;i<100;i++){let x=600+rand(i,101)*980,y=560+rand(i,102)*600;if(Math.hypot(x-1535,y-725)<310)continue;ctx.fillStyle=i%3?'#d4c88355':'#e8ddd055';ctx.beginPath();ctx.arc(x,y,1.3,0,6.28);ctx.fill()}
const entities=[...trees.map(o=>({y:o.y,draw:()=>drawTree(o)})),...stones.map(o=>({y:o.y,draw:()=>{ctx.fillStyle='#777b6c';ctx.beginPath();ctx.ellipse(o.x,o.y,o.r,o.r*.65,.3,0,6.28);ctx.fill();ctx.fillStyle='#a1a18c';ctx.beginPath();ctx.ellipse(o.x-o.r*.25,o.y-o.r*.3,o.r*.35,o.r*.2,-.3,0,6.28);ctx.fill()}})),...resources.filter(r=>r.count>0).map(o=>({y:o.y,draw:()=>drawResource(o)})),{y:player.y-15,draw:drawPlayer},{y:fire.y,draw:drawFire}].sort((a,b)=>a.y-b.y);for(const e of entities)e.draw();
// spring marker when nearby
if(nearWater()){ctx.strokeStyle='#d5cf9f99';ctx.lineWidth=1;ctx.beginPath();ctx.arc(player.x,player.y-37,12,0,6.28);ctx.stroke()}
ctx.restore();let minutes=((Math.floor(gameMinutes/60)%24)+24)%24;let night=(minutes>=20||minutes<6),dawn=minutes>=5&&minutes<8,dusk=minutes>=18&&minutes<21;let darkness=night?.48:dawn||dusk?.23:minutes>16?.09:0;let nearFire=fire.lit&&Math.hypot(player.x-fire.x,player.y-fire.y)<170;if(darkness>0){ctx.fillStyle=`rgba(13,23,36,${nearFire?darkness*.55:darkness})`;ctx.fillRect(0,0,W,H)}if(nearFire){let glow=ctx.createRadialGradient(W/2+(fire.x-player.x),H/2+(fire.y-player.y),10,W/2+(fire.x-player.x),H/2+(fire.y-player.y),190);glow.addColorStop(0,'#f3a64a35');glow.addColorStop(1,'#f3a64a00');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H)}
// atmospheric cool lake glow
if(nearWater()){let glow=ctx.createRadialGradient(W/2,H/2,80,W/2,H/2,420);glow.addColorStop(0,'#9cc7c00a');glow.addColorStop(1,'#9cc7c000');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H)}
}

